  { color: '#ff0800', text: 'Crisp Apple' },
  { color: '#4d9a17', text: 'Garden Broccoli' },
  { color: '#ff8c00', text: 'Sweet Carrot' },
  { color: '#614051', text: 'Royal Eggplant' },
