import type { PlaybackState, Prompt } from './types';
import { GoogleGenAI, LiveMusicFilteredPrompt } from '@google/genai';
import { PromptDjMidi } from './components/PromptDjMidi';
import { ToastMessage } from './components/ToastMessage';
import { LiveMusicHelper } from './utils/LiveMusicHelper';
import { AudioAnalyser } from './utils/AudioAnalyser';

const model = 'lyria-realtime-exp';

async function main() {
  const setupContainer = document.createElement('div');
  setupContainer.id = 'setup-screen';
  setupContainer.innerHTML = `
    <div class="setup-card">
      <h1>Veggie String Garden</h1>
      <p>To generate real-time orchestral music, you need to connect a paid API key from a project with billing enabled.</p>
      <button id="connect-btn">Connect Garden</button>
      <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" class="billing-link">Learn about billing</a>
    </div>
  `;
  document.body.appendChild(setupContainer);

  const connectBtn = setupContainer.querySelector('#connect-btn') as HTMLButtonElement;

  const startApp = async () => {
    setupContainer.remove();
    const initialPrompts = buildInitialPrompts();

    // Cast to any to fix inheritance recognition issues in this environment
    const pdjMidi = new PromptDjMidi(initialPrompts) as any;
    document.body.appendChild(pdjMidi);

    const toastMessage = new ToastMessage() as any;
    document.body.appendChild(toastMessage);

    const liveMusicHelper = new LiveMusicHelper(model);
    liveMusicHelper.setWeightedPrompts(initialPrompts);

    const audioAnalyser = new AudioAnalyser(liveMusicHelper.audioContext);
    liveMusicHelper.extraDestination = audioAnalyser.node;

    pdjMidi.addEventListener('prompts-changed', ((e: Event) => {
      const customEvent = e as CustomEvent<Map<string, Prompt>>;
      const prompts = customEvent.detail;
      liveMusicHelper.setWeightedPrompts(prompts);
    }));

    pdjMidi.addEventListener('play-pause', () => {
      liveMusicHelper.playPause();
    });

    liveMusicHelper.addEventListener('playback-state-changed', ((e: Event) => {
      const customEvent = e as CustomEvent<PlaybackState>;
      const playbackState = customEvent.detail;
      pdjMidi.playbackState = playbackState;
      playbackState === 'playing' ? audioAnalyser.start() : audioAnalyser.stop();
    }));

    liveMusicHelper.addEventListener('filtered-prompt', ((e: Event) => {
      const customEvent = e as CustomEvent<LiveMusicFilteredPrompt>;
      const filteredPrompt = customEvent.detail;
      toastMessage.show(filteredPrompt.filteredReason!)
      pdjMidi.addFilteredPrompt(filteredPrompt.text!);
    }));

    const errorToast = ((e: Event) => {
      const customEvent = e as CustomEvent<string>;
      const error = customEvent.detail;
      toastMessage.show(error);

      // If requested entity was not found, it's likely a billing/project issue
      if (error.includes('Requested entity was not found')) {
        window.location.reload(); // Quickest way to reset and prompt for key again
      }
    });

    liveMusicHelper.addEventListener('error', errorToast);
    pdjMidi.addEventListener('error', errorToast);

    audioAnalyser.addEventListener('audio-level-changed', ((e: Event) => {
      const customEvent = e as CustomEvent<number>;
      const level = customEvent.detail;
      pdjMidi.audioLevel = level;
    }));
  };

  const hasKey = await (window as any).aistudio.hasSelectedApiKey();
  if (hasKey) {
    startApp();
  } else {
    connectBtn.addEventListener('click', async () => {
      await (window as any).aistudio.openSelectKey();
      startApp();
    });
  }
}

function buildInitialPrompts() {
  const startOn = [...DEFAULT_PROMPTS]
    .sort(() => Math.random() - 0.5)
