import { GoogleGenAI } from '@google/genai';
import type { Prompt } from '../types';

export class VeggieArtHelper {
  private prompts: Map<string, Prompt> = new Map();

  constructor() {}

  public setPrompts(prompts: Map<string, Prompt>) {
    this.prompts = prompts;
  }

  public async generateArt(): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const activePrompts = [...this.prompts.values()]
      .filter(p => p.weight > 0)
      .sort((a, b) => b.weight - a.weight);

    if (activePrompts.length === 0) {
      throw new Error("Please enable at least one veggie to mix!");
    }

    const promptDescription = activePrompts
      .map(p => `${Math.round(p.weight * 100)}% ${p.text}`)
      .join(', ');

    const finalPrompt = `A high-quality, professional food photography shot of a surreal vegetable landscape or produce sculpture. It should feature a mix of: ${promptDescription}. Vibrant colors, studio lighting, clean dark background, 8k resolution.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: finalPrompt }]
      },
      config: {
        imageConfig: {
          aspectRatio: "1:1"
        }
      }
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image data returned from vision model.");
  }
}

