import type { PlaybackState, Prompt } from './types';
import { PromptDjMidi } from './components/PromptDjMidi';
import { ToastMessage } from './components/ToastMessage';
import { VeggieArtHelper } from './utils/VeggieArtHelper';
import { LiveMusicHelper } from './utils/LiveMusicHelper';
import { AudioAnalyser } from './utils/AudioAnalyser';

async function main() {
  const initialPrompts = buildInitialPrompts();

  // Cast to any to fix inheritance recognition issues in this environment
  const pdjMidi = new PromptDjMidi(initialPrompts) as any;
  document.body.appendChild(pdjMidi);

  const toastMessage = new ToastMessage() as any;
  document.body.appendChild(toastMessage);

  const artHelper = new VeggieArtHelper();
  const musicHelper = new LiveMusicHelper('gemini-2.5-flash-native-audio-preview-12-2025');
  const audioAnalyser = new AudioAnalyser(musicHelper.audioContext);

  // Wire up audio analysis to the UI
  audioAnalyser.addEventListener('audio-level-changed', ((e: Event) => {
    const customEvent = e as CustomEvent<number>;
    pdjMidi.audioLevel = customEvent.detail;
  }));

  pdjMidi.addEventListener('prompts-changed', ((e: Event) => {
    const customEvent = e as CustomEvent<Map<string, Prompt>>;
    const prompts = customEvent.detail;
    artHelper.setPrompts(prompts);
    musicHelper.updateMix(prompts);
  }));

  pdjMidi.addEventListener('play-pause', async () => {
    if (pdjMidi.playbackState === 'playing') {
      musicHelper.stop();
      audioAnalyser.stop();
      pdjMidi.playbackState = 'stopped';
    } else {
      try {
        pdjMidi.playbackState = 'loading';

        // Start audio session
        await musicHelper.start();
        audioAnalyser.start();

        // Trigger initial image render
        const imageUrl = await artHelper.generateArt();
        pdjMidi.currentImageUrl = imageUrl;

        pdjMidi.playbackState = 'playing';
      } catch (err: any) {
        pdjMidi.playbackState = 'stopped';
        toastMessage.show(`Startup failure: ${err.message}`);
      }
    }
  });

  const errorToast = ((e: Event) => {
    const customEvent = e as CustomEvent<string>;
    const error = customEvent.detail;
    toastMessage.show(error);
  });

  pdjMidi.addEventListener('error', errorToast);
}

function buildInitialPrompts() {
  const startOn = [...DEFAULT_PROMPTS]
    .sort(() => Math.random() - 0.5)
    .slice(0, 3);

  const prompts = new Map<string, Prompt>();
  const baseNote = 36;

  for (let i = 0; i < DEFAULT_PROMPTS.length; i++) {
    const promptId = `prompt-${i}`;
    const prompt = DEFAULT_PROMPTS[i];
    const { text, color } = prompt;
    prompts.set(promptId, {
      promptId,
      text,
      weight: startOn.includes(prompt) ? 1 : 0,
      cc: i,
      note: baseNote + i,
      color,
    });
  }

  return prompts;
}

const DEFAULT_PROMPTS = [
  { color: '#FF3B30', text: 'Crisp Red Apple' },
