import { GoogleGenAI, Modality } from '@google/genai';
import type { Prompt } from '../types';
import { decode, decodeAudioData } from './audio';
import { throttle } from './throttle';

export class LiveMusicHelper extends EventTarget {
  private ai: GoogleGenAI | null = null;
  private model: string;
  private session: any = null;
  private nextStartTime = 0;

  public readonly audioContext: AudioContext;
  private outputNode: GainNode;
  private sources: Set<AudioBufferSourceNode> = new Set();

  constructor(model: string) {
    super();
    this.model = model;
    this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    this.outputNode = this.audioContext.createGain();
    this.outputNode.connect(this.audioContext.destination);
  }

  public async start() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    this.session = await this.ai.live.connect({
      model: this.model,
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } },
        },
        systemInstruction: `You are a mystical Vegetable Symphony Engine. 
          You do not speak with words. Instead, you create melodic, rhythmic, and percussive sounds.
          When the user provides a vegetable mix, perform a short, abstract, musical soundscape representing those flavors.
          Use humming, whistling, mouth percussion, and rhythmic clicking. 
          Be creative, atmospheric, and entirely non-verbal. 
          Stay in a musical 'performing' state at all times.`,
      },
      callbacks: {
        onopen: () => {
          console.debug('Garden audio connected');
        },
        onmessage: async (message) => {
          const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
          if (base64Audio) {
            this.handleAudioData(base64Audio);
          }
          if (message.serverContent?.interrupted) {
            this.clearAudio();
          }
        },
        onerror: (e) => {
          this.dispatchEvent(new CustomEvent('error', { detail: 'Audio engine error. Please try again.' }));
        },
      }
    });

    // Send initial greeting (as a musical stir)
    this.session.send({ text: 'The garden is waking up. Perform a soft introductory hum.' });
  }

  private async handleAudioData(base64: string) {
    this.nextStartTime = Math.max(this.nextStartTime, this.audioContext.currentTime);
    const audioBuffer = await decodeAudioData(
      decode(base64),
      this.audioContext,
      24000,
      1
    );
    const source = this.audioContext.createBufferSource();
    source.buffer = audioBuffer;
    source.connect(this.outputNode);
    source.onended = () => this.sources.delete(source);
    source.start(this.nextStartTime);
    this.nextStartTime += audioBuffer.duration;
    this.sources.add(source);
  }

  private clearAudio() {
    for (const source of this.sources) {
      try { source.stop(); } catch(e) {}
    }
    this.sources.clear();
    this.nextStartTime = 0;
  }

  public stop() {
    if (this.session) {
      this.session.close();
      this.session = null;
    }
    this.clearAudio();
  }

  public readonly updateMix = throttle((prompts: Map<string, Prompt>) => {
    if (!this.session) return;

    const active = Array.from(prompts.values())
      .filter(p => p.weight > 0.1)
      .sort((a, b) => b.weight - a.weight);

    if (active.length === 0) return;

    const description = active.map(p => `${Math.round(p.weight * 50)}% ${p.text}`).join(', ');
    const message = `The mix has changed. Now performing: ${description}. Shift your musical tone to match this new garden state.`;

    this.session.send({ text: message });
  }, 1500); // Throttled to avoid overwhelming the live session
}

