      box-shadow: 0 0 30px rgba(76, 217, 100, 0.2);
      border: 4px solid rgba(255, 255, 255, 0.1);
      background: #000;
      transition: transform 0.1s ease-out;
    }
    #vision-canvas {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: opacity 0.5s;
    }
    .loading #vision-canvas {
      opacity: 0.3;
      filter: blur(5px);
    }
    #loader-overlay {
      position: absolute;
      inset: 0;
      display: none;
      align-items: center;
      justify-content: center;
      color: #4CD964;
      font-weight: bold;
      text-shadow: 0 0 10px #000;
      background: rgba(0,0,0,0.3);
      text-transform: uppercase;
      letter-spacing: 2px;
    }
    .loading #loader-overlay {
      display: flex;
    }
    #garden-input {
      display: flex;
      gap: 10px;
      margin-top: 20px;
      padding: 10px;
      background: rgba(255, 255, 255, 0.05);
      border-radius: 12px;
      border: 1px solid rgba(255, 255, 255, 0.1);
      backdrop-filter: blur(10px);
      width: min(80vmin, 600px);
      box-sizing: border-box;
    }
    #garden-input input {
      flex: 1;
      background: #000;
      border: 1px solid #333;
      color: #fff;
      padding: 10px 15px;
      border-radius: 8px;
      font-size: 1.6vmin;
      outline: none;
    }
    #garden-input button {
      background: #4CD964;
      color: #000;
      border: none;
      padding: 0 20px;
      border-radius: 8px;
      font-weight: bold;
      cursor: pointer;
    }
    #grid {
      width: 80vmin;
      height: 45vmin;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 2vmin;
      margin: 1vmin 0;
    }
    play-pause-button {
      width: 10vmin;
      cursor: pointer;
      pointer-events: auto;
    }
    #buttons {
      position: absolute;
      top: 10px;
      left: 10px;
      display: flex;
      gap: 5px;
    }
    .midi-btn {
      font: inherit;
      cursor: pointer;
      color: #fff;
      background: #222;
      border: 1px solid #444;
      border-radius: 4px;
      padding: 5px 10px;
    }
    .midi-btn.active { background: #fff; color: #000; }
  `;

  private prompts: Map<string, Prompt>;
  private midiDispatcher: MidiDispatcher;

  @property({ type: String }) public playbackState: PlaybackState = 'stopped';
  @property({ type: String }) public currentImageUrl: string = 'https://images.unsplash.com/photo-1540189549336-e6e99c3679fe?auto=format&fit=crop&q=80&w=1000';
  @property({ type: Number }) public audioLevel = 0;

  @state() private showMidi = false;
  @state() private midiInputIds: string[] = [];
  @state() private activeMidiInputId: string | null = null;

  @query('#veggie-field') private veggieInput!: HTMLInputElement;

  constructor(initialPrompts: Map<string, Prompt>) {
    super();
    this.prompts = initialPrompts;
    this.midiDispatcher = new MidiDispatcher();
  }

  private handlePromptChanged(e: CustomEvent<Prompt>) {
    const { promptId, text, weight, cc, note } = e.detail;
    const prompt = this.prompts.get(promptId);
    if (!prompt) return;
    prompt.text = text;
    prompt.weight = weight;
    prompt.cc = cc;
    prompt.note = note;
    this.prompts = new Map(this.prompts);
    (this as any).requestUpdate();
    (this as any).dispatchEvent(new CustomEvent('prompts-changed', { detail: this.prompts }));
  }

  private readonly makeBackground = throttle(() => {
    const bg: string[] = [];
    [...this.prompts.values()].forEach((p, i) => {
      const alpha = Math.round(Math.min(p.weight * 0.4, 0.4) * 0xff).toString(16).padStart(2, '0');
      const x = (i % 4) / 3;
      const y = Math.floor(i / 4) / 3;
      bg.push(`radial-gradient(circle at ${x * 100}% ${y * 100}%, ${p.color}${alpha} 0px, ${p.color}00 30%)`);
    });
    return bg.join(', ');
  }, 50);

  private plantVeggie() {
    const text = this.veggieInput.value.trim();
    if (!text) return;
    const target = [...this.prompts.values()].sort((a, b) => a.weight - b.weight)[0];
    if (target) {
      target.text = text;
      target.weight = 1.0;
      this.handlePromptChanged(new CustomEvent('prompt-changed', { detail: target }));
    }
    this.veggieInput.value = '';
  }

  private async toggleMidi() {
    this.showMidi = !this.showMidi;
    if (this.showMidi) {
      this.midiInputIds = await this.midiDispatcher.getMidiAccess();
      this.activeMidiInputId = this.midiDispatcher.activeMidiInputId;
    }
  }

  render() {
    const visionStyle = styleMap({
      transform: `scale(${1 + this.audioLevel * 0.1})`,
      boxShadow: `0 0 ${20 + this.audioLevel * 50}px rgba(76, 217, 100, ${0.2 + this.audioLevel})`
    });

    return html`
      <div id="background" style=${styleMap({ backgroundImage: this.makeBackground() })}></div>

      <div id="buttons">
        <button class="midi-btn ${this.showMidi ? 'active' : ''}" @click=${this.toggleMidi}>MIDI</button>
      </div>

      <div id="garden-input">
        <input id="veggie-field" placeholder="Add to the garden (e.g. Asparagus)..." @keydown=${(e:any)=>e.key==='Enter'&&this.plantVeggie()}>
        <button @click=${this.plantVeggie}>Plant</button>
      </div>

      <div id="vision-container" style=${visionStyle} class=${this.playbackState === 'loading' ? 'loading' : ''}>
        <img id="vision-canvas" src=${this.currentImageUrl} alt="Veggie Vision">
        <div id="loader-overlay">Growing Symphony...</div>
      </div>

      <div id="grid">${this.renderPrompts()}</div>

      <play-pause-button .playbackState=${this.playbackState} @click=${() => (this as any).dispatchEvent(new CustomEvent('play-pause'))}></play-pause-button>
    `;
  }

  private renderPrompts() {
    return [...this.prompts.values()].map((p) => html`
      <prompt-controller
        promptId=${p.promptId}
        text=${p.text}
        weight=${p.weight}
        color=${p.color}
        cc=${p.cc}
        note=${p.note}
        audioLevel=${this.audioLevel}
        .showCC=${this.showMidi}
        .midiDispatcher=${this.midiDispatcher}
        @prompt-changed=${this.handlePromptChanged}>
      </prompt-controller>
    `);
  }
}

